import { Order, OrderState } from "../domain/order";
import { Product } from "../domain/product";
import { OrderRepository, ProductRepository } from "../domain/repositories";

export class InMemoryOrderRepository implements OrderRepository {
  private readonly orders = new Map<string, Order>();
  public findById(id: string): Order | undefined { return this.orders.get(id); }
  public save(order: Order): void { this.orders.set(order.id, order); }
  public listByState(state?: OrderState): Order[] {
    return [...this.orders.values()].filter((order) => state === undefined || order.state === state);
  }
}

export class InMemoryProductRepository implements ProductRepository {
  private readonly products = new Map<string, Product>();
  public findById(id: string): Product | undefined { return this.products.get(id); }
  public save(product: Product): void { this.products.set(product.id, product); }
  public list(): Product[] { return [...this.products.values()]; }
}

