import { Request, Response, Router } from "express";
import { CatalogueService } from "../application/catalogue-service";
import { PlaceOrderInput } from "../application/dtos";
import { OrderService } from "../application/order-service";
import { OrderState } from "../domain/order";

const states: readonly OrderState[] = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"];
const isState = (value: unknown): value is OrderState => typeof value === "string" && states.includes(value as OrderState);

export class OrderController {
  public constructor(private readonly orders: OrderService, private readonly catalogue: CatalogueService) {}

  public router(): Router {
    const router = Router();
    router.post("/products", this.handle((req) => this.catalogue.add(req.body.id, req.body.name, req.body.stock), 201));
    router.get("/products", this.handle(() => this.catalogue.list()));
    router.post("/orders", this.handle((req) => this.orders.place(req.body as PlaceOrderInput), 201));
    router.get("/orders", this.handle((req) => {
      const state = req.query.state;
      if (state !== undefined && !isState(state)) throw new Error("Invalid order state");
      return this.orders.list(state);
    }));
    router.patch("/orders/:id/state", this.handle((req) => {
      if (!isState(req.body.state)) throw new Error("Invalid order state");
      return this.orders.advance(this.orderId(req), req.body.state);
    }));
    router.post("/orders/:id/cancel", this.handle((req) => this.orders.cancel(this.orderId(req))));
    return router;
  }

  private handle(action: (request: Request) => unknown, status = 200) {
    return (request: Request, response: Response): void => {
      try { response.status(status).json(action(request)); }
      catch (error: unknown) { response.status(400).json({ error: error instanceof Error ? error.message : "Request failed" }); }
    };
  }

  private orderId(request: Request): string {
    const id = request.params.id;
    if (typeof id !== "string" || !id.trim()) throw new Error("Order id is required");
    return id;
  }
}

